def shortestAlternatingPaths(n: int, redEdges: list[list[int]], blueEdges: list[list[int]]) -> list[int]:
    from collections import defaultdict, deque
    adj = {0: defaultdict(list), 1: defaultdict(list)}
    for u, v in redEdges: adj[0][u].append(v)
    for u, v in blueEdges: adj[1][u].append(v)
    dist = [[float('inf'), float('inf')] for _ in range(n)]
    dist[0][0] = dist[0][1] = 0
    q = deque([(0, 0, 0), (0, 1, 0)])  # (u, last_color, steps)
    while q:
        u, color, d = q.popleft()
        next_color = 1 - color
        for v in adj[next_color][u]:
            if d + 1 < dist[v][next_color]:
                dist[v][next_color] = d + 1
                q.append((v, next_color, d + 1))
    res = []
    for i in range(n):
        m = min(dist[i][0], dist[i][1])
        res.append(m if m != float('inf') else -1)
    return res

